74	-- ────────────────────────────────────────────────────────────────────────────
75	-- PART 2: Fix RLS policies that are always-true for writes
76	-- ────────────────────────────────────────────────────────────────────────────
77	-- Strategy per stub table:
78	--   DROP the overly permissive existing policy (or policies).
79	--   CREATE a SELECT policy with USING (true)   — reads stay open.
80	--   CREATE INSERT policy WITH CHECK (auth.uid() IS NOT NULL).
81	--   CREATE UPDATE policy USING + WITH CHECK (auth.uid() IS NOT NULL).
82	--   CREATE DELETE policy USING (auth.uid() IS NOT NULL).
83	--
84	-- Tables that already have good write-gate policies (e.g. notifications,
85	-- activity_log, sms_logs) are NOT touched here.
86	-- ────────────────────────────────────────────────────────────────────────────
87	
