402	-- The _all / _select USING (true) policies from 0006 are the problem.
403	-- 0013 already added better admin-scoped SELECT + unrestricted INSERT.
404	-- We only need to fix the blanket USING (true) SELECT from 0006.
405	DROP POLICY IF EXISTS system_error_logs_select ON system_error_logs;
406	DROP POLICY IF EXISTS system_error_logs_admin  ON system_error_logs;
407	DROP POLICY IF EXISTS system_error_logs_insert ON system_error_logs;
408	
409	-- Admins (boldteq.com / rankora.co email) can read all error logs.
410	-- Any authenticated user can insert (client-side error reporting).
411	DROP POLICY IF EXISTS system_error_logs_select ON system_error_logs;
412	CREATE POLICY system_error_logs_select ON system_error_logs
413	  FOR SELECT TO authenticated
414	  USING (
415	    EXISTS (
416	      SELECT 1 FROM user_roles
417	      WHERE user_id = auth.uid() AND role = 'admin'
418	    )
419	  );
420	
421	DROP POLICY IF EXISTS system_error_logs_insert ON system_error_logs;
422	CREATE POLICY system_error_logs_insert ON system_error_logs
423	  FOR INSERT TO authenticated
424	  WITH CHECK (auth.uid() IS NOT NULL);
